<?php
declare(strict_types=1);
requireRole($user,['provincial_admin']);
if(!$portalReady)return;
$modern=ChurchPortal::officerRegistrationReady($db);
$extra=$modern?',r.requested_church_name,r.requested_church_type':'';
$requests=$db->query("SELECT r.id,r.full_name,r.email,r.phone,r.bank_name,r.account_name,r.account_last4,r.created_at,r.parish_id,h.node_name,h.node_type $extra FROM church_registrations r LEFT JOIN church_hierarchy h ON h.id=r.parish_id WHERE r.status='pending' ORDER BY r.id LIMIT 100")->fetchAll();
$reviewChurches=$modern?ChurchPortal::directory($db):[];
?>
<section class="panel"><div class="panel-heading"><div><h2>Officer registrations</h2><p>Verify identity and church authorization independently. Roles follow the linked Parish, Area or Zone.</p></div><span class="chip"><?= count($requests) ?> awaiting review (up to 100)</span></div><?php if(!$requests): ?><div class="empty"><span>✓</span><h3>You’re all caught up</h3><p>New officer applications will appear here for approval.</p></div><?php endif ?>
<?php foreach($requests as $request): ?><article class="review-card"><div><span class="badge pending">Pending approval</span><h3><?= e($request['node_name'] ?? $request['requested_church_name'] ?? 'Unlinked church') ?></h3><p><?= e(ucfirst($request['node_type'] ?? $request['requested_church_type'] ?? 'Unknown level')) ?></p><p><?= e($request['full_name'].' · '.$request['email'].' · '.$request['phone']) ?></p><?php if($request['account_last4']!==''): ?><p class="muted small">Legacy church account: <?= e($request['bank_name'].' · '.$request['account_name'].' · ••••••'.$request['account_last4']) ?></p><?php endif ?></div><form method="post" class="review-actions"><?php hiddenAction('registration_review') ?><input type="hidden" name="registration_id" value="<?= (int)$request['id'] ?>">
<?php if(empty($request['parish_id'])): ?><p class="notice small">Unlisted name — check for similar churches. If genuinely absent, add it using Quick add with its correct parent and parish code, then return here and link it. Approval cannot create a church.</p><label>Link verified church<select name="resolved_unit_id" data-unit-search><option value="">Choose a verified church before approval</option><?php foreach($reviewChurches as $church): ?><option value="<?= (int)$church['id'] ?>"><?= e(unitLabel($church)) ?></option><?php endforeach ?></select></label><?php endif ?>
<button name="decision" value="approved" class="primary">Approve account</button><button name="decision" value="rejected" class="secondary">Reject</button></form></article><?php endforeach ?></section>
